// Extension method: "gruda" um método novo na List<Documento>
public static class DocumentoExtensions
{
    public static int ContarPorStatus(this List<Documento> documentos, string status)
    {
        if (documentos == null)
            return 0;

        return documentos
            .Count(d => string.Equals(d.Status, status, StringComparison.OrdinalIgnoreCase));
    }
}

