@Component({ selector: 'app-chat-cliente', templateUrl: './chat-cliente.html' })
export class ChatClienteComponent implements OnInit {
  private chatService = inject(ChatService);   // serviço singleton (providedIn: 'root')
  mensagens: Mensagem[] = [];

  ngOnInit(): void {
    // a cada 5 segundos marca as mensagens como lidas
    interval(5000).subscribe(() => {
      console.log('marcando como lidas');
      this.chatService.marcarComoLidas();
    });

    // mensagens novas que chegam pelo hub (BehaviorSubject no serviço)
    this.chatService.mensagens$.subscribe(lista => this.mensagens = lista);

    // histórico vem da API (HTTP)
    this.chatService.obterHistorico().subscribe(h => this.mensagens = h);
  }
}

// Retorna o documento para download, validando acesso.
public async Task<Retorno> ObterParaDownload(string usuarioId, string documentoId)
{
    var documento = await _repository.GetById(documentoId);
    if (documento != null)
    {
        if (!documento.Excluido)
        {
            if (await _permissao.PodeVer(usuarioId, documento.ClienteId))
            {
                var url = await _storage.GerarUrlTemporaria(documento.Caminho);
                return Retorno.Ok(url);
            }
            else
            {
                return Retorno.Erro("Sem permissão");
            }
        }
        else
        {
            return Retorno.Erro("Documento excluído");
        }
    }
    else
    {
        return Retorno.Erro("Documento não encontrado");
    }
}

