// Texto do badge de prazo de um documento
public string TextoPrazo(Documento documento) => documento?.Prazo switch
{
    null => "Sem prazo",
    var p when p < DateTime.Today => "Vencido",
    var p when p == DateTime.Today => "Vence hoje",
    var p when p <= DateTime.Today.AddDays(7) => $"Vence em {(p.Value - DateTime.Today).Days} dias",
    _ => "No prazo"
};

