Versão simples:
public string TextoPrazo(Documento documento)
{
    if (documento == null || documento.Prazo == null)
        return "Sem prazo";

    var prazo = documento.Prazo.Value;
    var hoje = DateTime.Today;

    if (prazo < hoje)
        return "Vencido";

    if (prazo == hoje)
        return "Vence hoje";

    if (prazo <= hoje.AddDays(7))
        return $"Vence em {(prazo - hoje).Days} dias";

    return "No prazo";
}
(a) 05/11 → 'Vence em 6 dias' (31/10 a 05/11; está dentro dos 7 dias). (b) 'Sem prazo'. (c) 'Sem prazo' — documento?.Prazo vira null, cai no case null (não estoura).
